-- GENERATED by node src/build-attendance.mjs; edit the source/gates, then regenerate.
-- Attendance schema SHA256: 43f9a7e4f8299631b933b0d0e5f1fca3f4f59a25de0a204a350f06298e63e982
begin;
-- ════════════════════════════════════════════════════════════════════════
--  TEAM APP — staff attendance, multi-tenant
--
--  Run this ONCE in the Supabase SQL editor on a NEW project.
--  "Multi-tenant" means every client company lives in this one database,
--  fully walled off from each other. Company A can never read Company B's
--  staff, aero_shifts or messages — that is enforced by the database itself
--  (Row Level Security), not by the website. If someone opened the browser
--  console and tried, Postgres would still refuse.
-- ════════════════════════════════════════════════════════════════════════


-- ── TABLES ──────────────────────────────────────────────────────────────

create table if not exists aero_companies (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  created_at  timestamptz not null default now()
);

-- Where staff are allowed to clock in from. A company can have several
-- (247 has yards; A-Z has the shop counter).
create table if not exists aero_worksites (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid not null references aero_companies(id) on delete cascade,
  name        text not null,
  lat         double precision not null,
  lng         double precision not null,
  -- How close you must be, in metres. 150m is a sane default: GPS on a
  -- phone is routinely 20-50m out, and a tight radius means honest staff
  -- get rejected standing in the right place, which kills trust in the app
  -- faster than any amount of clock-in fiddling.
  radius_m    integer not null default 150,
  created_at  timestamptz not null default now()
);

-- One row per person. id matches the Supabase auth user id.
create table if not exists aero_profiles (
  id          uuid primary key references auth.users(id) on delete cascade,
  company_id  uuid not null references aero_companies(id) on delete cascade,
  full_name   text not null default '',
  role        text not null default 'staff' check (role in ('owner','admin','staff')),
  active      boolean not null default true,
  created_at  timestamptz not null default now()
);
create index if not exists aero_profiles_company_idx on aero_profiles(company_id);

-- One row per clock-in. clock_out_at null means "still on shift".
create table if not exists aero_shifts (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references aero_companies(id) on delete cascade,
  user_id           uuid not null references aero_profiles(id) on delete cascade,
  worksite_id       uuid references aero_worksites(id) on delete set null,

  clock_in_at       timestamptz not null default now(),
  clock_in_lat      double precision,
  clock_in_lng      double precision,
  clock_in_metres   integer,          -- how far from the worksite they were
  clock_in_ok       boolean,          -- inside the radius?

  clock_out_at      timestamptz,
  clock_out_lat     double precision,
  clock_out_lng     double precision,
  clock_out_metres  integer,
  clock_out_ok      boolean,

  note              text not null default '',
  created_at        timestamptz not null default now()
);
create index if not exists aero_shifts_company_idx on aero_shifts(company_id, clock_in_at desc);
create index if not exists aero_shifts_open_idx on aero_shifts(user_id) where clock_out_at is null;


-- ── WHO AM I? ───────────────────────────────────────────────────────────
--
-- ⚠️ READ THIS BEFORE CHANGING ANY POLICY BELOW.
--
-- A policy ON a table that queries THAT SAME table is infinite recursion.
-- Postgres aborts with error 42P17 and every query fails. This exact bug
-- cost an evening on another project, and it presented as "you are not
-- allowed" rather than as a crash, which sent us hunting in the wrong place
-- for hours.
--
-- `security definer` is the fix: the function runs as its owner, so the
-- query inside it is NOT subject to RLS and cannot recurse. Every policy
-- calls these two functions instead of querying aero_profiles directly.

create or replace function aero_current_company_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select company_id from aero_profiles where id = auth.uid()
$$;

create or replace function aero_is_manager()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from aero_profiles
    where id = auth.uid() and role in ('owner','admin') and active
  )
$$;


-- ── ADD-ONS: WHAT THIS CLIENT HAS BEEN GIVEN ────────────────────────────
--
-- Two different things, kept apart on purpose:
--
--   ADD-ON   the owner decides on /platform whether a client has a feature at
--            all. A client cannot switch on something they were never given.
--   SETTING  the client's own manager decides how a feature they do have
--            behaves (the overtime threshold, whether pay is shown, and so on).
--
-- Only what is switched OFF is stored. No row means the client has the feature,
-- so adding this changes nothing for anybody already live until something is
-- unticked.
--
-- Only the platform Edge Function writes here, with the service key: there is no
-- insert, update or delete grant, so a client's manager cannot hand themselves a
-- feature from the browser.
create table if not exists aero_company_features (
  company_id uuid not null references aero_companies(id) on delete cascade,
  feature    text not null check (feature in
               ('rota','pay','breaks','notices','handover','overtime','incidents','staff_profiles')),
  enabled    boolean not null,
  updated_at timestamptz not null default now(),
  primary key (company_id, feature)
);
alter table aero_company_features enable row level security;

drop policy if exists aero_company_features_read on aero_company_features;
create policy aero_company_features_read on aero_company_features for select to authenticated
  using (company_id = aero_current_company_id());

revoke all on table aero_company_features from anon, authenticated;
grant select on table aero_company_features to authenticated;

create or replace function aero_has_feature(p_feature text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select cf.enabled from aero_company_features cf
      where cf.company_id = aero_current_company_id() and cf.feature = p_feature),
    true)
$$;

revoke execute on function aero_has_feature(text) from public, anon;
grant execute on function aero_has_feature(text) to authenticated;


-- ── DISTANCE ────────────────────────────────────────────────────────────
--
-- Haversine, in metres. Deliberately a database function, not browser code:
-- the phone reports where it claims to be, but the DATABASE decides whether
-- that counts. Otherwise anyone could edit the JavaScript and mark their own
-- clock-in as on-site.
--
-- Be honest about what this does and doesn't stop: it stops someone clocking
-- in from bed. It does not stop a determined faker with a spoofing app on a
-- rooted phone. Sell it as an honesty check, not surveillance.

create or replace function aero_metres_between(
  lat1 double precision, lng1 double precision,
  lat2 double precision, lng2 double precision
) returns double precision
language sql immutable as $$
  select 6371000 * 2 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) *
    power(sin(radians(lng2 - lng1) / 2), 2)
  ))
$$;


-- ── CLOCK IN / OUT ──────────────────────────────────────────────────────
--
-- Done as functions rather than plain inserts so the rules live in one
-- place the browser cannot argue with: you cannot be on two aero_shifts at once,
-- you cannot clock out of a shift that is not yours, and the distance check
-- is applied server-side every time.

create or replace function aero_clock_in(
  p_worksite_id uuid,
  p_lat double precision default null,
  p_lng double precision default null
) returns aero_shifts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_company uuid := aero_current_company_id();
  v_site    aero_worksites;
  v_metres  double precision;
  v_ok      boolean;
  v_shift   aero_shifts;
begin
  if v_company is null then
    raise exception 'No profile for this user — ask your manager to add you.';
  end if;

  -- Serialise simultaneous clock-ins for one person before checking the open shift.
  perform 1 from aero_profiles where id = auth.uid() and active for update;
  if not found then raise exception 'Your account is inactive.'; end if;

  -- Already on shift? Hand back the open one rather than opening a second.
  -- A double tap on a slow connection must not create two aero_shifts.
  select * into v_shift from aero_shifts
   where user_id = auth.uid() and clock_out_at is null
   order by clock_in_at desc limit 1;
  if found then
    return v_shift;
  end if;

  select * into v_site from aero_worksites
   where id = p_worksite_id and company_id = v_company;
  if not found then
    raise exception 'Unknown worksite.';
  end if;

  if p_lat is not null and p_lng is not null then
    v_metres := aero_metres_between(p_lat, p_lng, v_site.lat, v_site.lng);
    v_ok := v_metres <= v_site.radius_m;
  else
    -- No location given (permission denied, or indoors with no fix). Record
    -- it honestly as unverified rather than refusing — a refused clock-in
    -- means an unpaid shift, and that is a far worse failure than a flagged
    -- one a manager can check.
    v_metres := null;
    v_ok := null;
  end if;

  insert into aero_shifts (company_id, user_id, worksite_id,
                      clock_in_lat, clock_in_lng, clock_in_metres, clock_in_ok)
  values (v_company, auth.uid(), p_worksite_id,
          p_lat, p_lng, round(v_metres)::int, v_ok)
  returning * into v_shift;

  return v_shift;
end;
$$;

create or replace function aero_clock_out(
  p_lat double precision default null,
  p_lng double precision default null,
  p_note text default ''
) returns aero_shifts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_site   aero_worksites;
  v_metres double precision;
  v_ok     boolean;
  v_shift  aero_shifts;
begin
  select * into v_shift from aero_shifts
   where user_id = auth.uid() and clock_out_at is null
   order by clock_in_at desc limit 1;
  if not found then
    raise exception 'You are not clocked in.';
  end if;

  if v_shift.worksite_id is not null and p_lat is not null and p_lng is not null then
    select * into v_site from aero_worksites where id = v_shift.worksite_id;
    if found then
      v_metres := aero_metres_between(p_lat, p_lng, v_site.lat, v_site.lng);
      v_ok := v_metres <= v_site.radius_m;
    end if;
  end if;

  update aero_shifts set
    clock_out_at     = now(),
    clock_out_lat    = p_lat,
    clock_out_lng    = p_lng,
    clock_out_metres = round(v_metres)::int,
    clock_out_ok     = v_ok,
    note             = coalesce(nullif(p_note, ''), note)
  where id = v_shift.id
  returning * into v_shift;

  return v_shift;
end;
$$;


-- ── ROW LEVEL SECURITY ──────────────────────────────────────────────────
-- Nothing is readable until a policy says so. Every policy is scoped to the
-- caller's own company.

alter table aero_companies enable row level security;
alter table aero_worksites enable row level security;
alter table aero_profiles  enable row level security;
alter table aero_shifts    enable row level security;

-- Companies: you can see your own, only an owner/admin can rename it.
drop policy if exists aero_companies_read on aero_companies;
create policy aero_companies_read on aero_companies for select to authenticated
  using (id = aero_current_company_id());

drop policy if exists aero_companies_update on aero_companies;
create policy aero_companies_update on aero_companies for update to authenticated
  using (id = aero_current_company_id() and aero_is_manager());

-- Worksites: everyone in the company can see them (the app needs the list
-- to clock in against); only managers can change them.
drop policy if exists aero_worksites_read on aero_worksites;
create policy aero_worksites_read on aero_worksites for select to authenticated
  using (company_id = aero_current_company_id());

drop policy if exists aero_worksites_write on aero_worksites;
create policy aero_worksites_write on aero_worksites for all to authenticated
  using (company_id = aero_current_company_id() and aero_is_manager())
  with check (company_id = aero_current_company_id() and aero_is_manager());

-- Profiles: everyone sees their colleagues (needed to show names on the
-- board); only managers can add, edit or deactivate people.
drop policy if exists aero_profiles_read on aero_profiles;
create policy aero_profiles_read on aero_profiles for select to authenticated
  using (company_id = aero_current_company_id());

drop policy if exists aero_profiles_self_update on aero_profiles;
create policy aero_profiles_self_update on aero_profiles for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid() and company_id = aero_current_company_id());

drop policy if exists aero_profiles_manage on aero_profiles;
create policy aero_profiles_manage on aero_profiles for all to authenticated
  using (company_id = aero_current_company_id() and aero_is_manager())
  with check (company_id = aero_current_company_id() and aero_is_manager());

-- Shifts: you always see your own. Managers see the whole company's.
-- Writes go through aero_clock_in()/aero_clock_out(), but a manager can correct a
-- row by hand — people forget to clock out and that has to be fixable.
drop policy if exists aero_shifts_read on aero_shifts;
create policy aero_shifts_read on aero_shifts for select to authenticated
  using (company_id = aero_current_company_id()
         and (user_id = auth.uid() or aero_is_manager()));

drop policy if exists aero_shifts_manage on aero_shifts;
create policy aero_shifts_manage on aero_shifts for all to authenticated
  using (company_id = aero_current_company_id() and aero_is_manager())
  with check (company_id = aero_current_company_id() and aero_is_manager());


-- ── LIVE BOARD ──────────────────────────────────────────────────────────
-- Who is on shift right now, as the admin screen draws it.
-- security_invoker is essential: without it a view runs as its owner and
-- ignores RLS, so anyone with the public key could read every company's
-- on-shift staff. With it, the aero_shifts/aero_profiles policies above apply.
create or replace view aero_on_shift_now with (security_invoker = true) as
  select s.id           as shift_id,
         s.company_id,
         s.user_id,
         p.full_name,
         w.name         as worksite,
         s.clock_in_at,
         s.clock_in_ok,
         s.clock_in_metres,
         extract(epoch from (now() - s.clock_in_at))/3600 as hours_so_far
    from aero_shifts s
    join aero_profiles p  on p.id = s.user_id
    left join aero_worksites w on w.id = s.worksite_id
   where s.clock_out_at is null;


-- ── ACCESS ──────────────────────────────────────────────────────────────
-- Signed-out visitors (anon) get nothing. Signed-in users get table access,
-- and RLS then limits them to their own company. Set explicitly rather than
-- relying on Supabase's defaults, which differ between projects.
revoke all on table aero_companies, aero_worksites, aero_profiles, aero_shifts, aero_on_shift_now from anon;
grant select, insert, update, delete on table aero_companies, aero_worksites, aero_profiles, aero_shifts to authenticated;
grant select on table aero_on_shift_now to authenticated;

revoke execute on function aero_clock_in(uuid, double precision, double precision) from public, anon;
revoke execute on function aero_clock_out(double precision, double precision, text) from public, anon;
grant execute on function aero_clock_in(uuid, double precision, double precision) to authenticated;
grant execute on function aero_clock_out(double precision, double precision, text) to authenticated;

-- Attendance corrections: originals and decisions remain available for review.
create table if not exists aero_shift_corrections (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references aero_companies(id) on delete cascade,
  shift_id uuid not null references aero_shifts(id) on delete cascade,
  user_id uuid not null references aero_profiles(id) on delete cascade,
  original_in timestamptz not null,
  original_out timestamptz,
  requested_in timestamptz not null,
  requested_out timestamptz not null,
  reason text not null check (length(trim(reason)) between 1 and 1000),
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  review_note text not null default '',
  reviewed_by uuid references aero_profiles(id),
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  check (requested_out > requested_in)
);
create unique index if not exists aero_corrections_one_pending on aero_shift_corrections(shift_id) where status = 'pending';
create index if not exists aero_corrections_company_date on aero_shift_corrections(company_id, created_at desc);
alter table aero_shift_corrections enable row level security;
drop policy if exists corrections_read on aero_shift_corrections;
create policy corrections_read on aero_shift_corrections for select to authenticated
  using (company_id = aero_current_company_id() and (user_id = auth.uid() or aero_is_manager()));
revoke all on aero_shift_corrections from anon, authenticated;
grant select on aero_shift_corrections to authenticated;

-- Staff cannot change their own company, role or active status.
drop policy if exists aero_profiles_self_update on aero_profiles;

create or replace function aero_request_shift_correction(
  p_shift_id uuid, p_in timestamptz, p_out timestamptz, p_reason text
) returns aero_shift_corrections
language plpgsql security definer set search_path = public as $$
declare v_shift aero_shifts; v_request aero_shift_corrections;
begin
  if not exists (select 1 from aero_profiles where id = auth.uid() and active) then
    raise exception 'Your account is inactive.';
  end if;
  select * into v_shift from aero_shifts where id = p_shift_id
    and user_id = auth.uid() and company_id = aero_current_company_id() for update;
  if not found then raise exception 'Shift not found.'; end if;
  if p_in is null or p_out is null or not isfinite(p_in) or not isfinite(p_out)
     or p_out <= p_in or p_out > now() then
    raise exception 'Enter a start and end time in the past, with the end after the start.';
  end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then
    raise exception 'Enter a reason of up to 1000 characters.';
  end if;
  if p_in = v_shift.clock_in_at and p_out is not distinct from v_shift.clock_out_at then
    raise exception 'The requested times are unchanged.';
  end if;
  if exists (select 1 from aero_shift_corrections where shift_id = p_shift_id and status = 'pending') then
    raise exception 'This shift already has a pending correction.';
  end if;
  insert into aero_shift_corrections(company_id, shift_id, user_id, original_in, original_out,
      requested_in, requested_out, reason)
    values (v_shift.company_id, v_shift.id, auth.uid(), v_shift.clock_in_at,
      v_shift.clock_out_at, p_in, p_out, trim(p_reason)) returning * into v_request;
  return v_request;
end;
$$;

create or replace function aero_review_shift_correction(p_id uuid, p_approve boolean, p_note text default '')
returns aero_shift_corrections
language plpgsql security definer set search_path = public as $$
declare v_request aero_shift_corrections; v_shift aero_shifts;
begin
  if not coalesce(aero_is_manager(), false) then raise exception 'Manager access required.'; end if;
  if p_approve is null then raise exception 'Choose approve or reject.'; end if;
  if length(coalesce(p_note, '')) > 1000 then raise exception 'Review note is too long.'; end if;
  select * into v_request from aero_shift_corrections where id = p_id
    and company_id = aero_current_company_id() for update;
  if not found then raise exception 'Correction not found.'; end if;
  if v_request.user_id = auth.uid() then raise exception 'Another manager must review your own correction.'; end if;
  if v_request.status <> 'pending' then raise exception 'This correction has already been reviewed.'; end if;
  if p_approve then
    select * into v_shift from aero_shifts where id = v_request.shift_id for update;
    if v_shift.clock_in_at is distinct from v_request.original_in
       or v_shift.clock_out_at is distinct from v_request.original_out then
      raise exception 'This shift has changed since the request. Reject it and ask for a new request.';
    end if;
    if exists (select 1 from aero_shifts where user_id = v_request.user_id and id <> v_shift.id
      and clock_in_at < v_request.requested_out
      and coalesce(clock_out_at, 'infinity'::timestamptz) > v_request.requested_in) then
      raise exception 'These times overlap another shift.';
    end if;
    update aero_shifts set clock_in_at = v_request.requested_in, clock_out_at = v_request.requested_out
      where id = v_request.shift_id;
  end if;
  update aero_shift_corrections set status = case when p_approve then 'approved' else 'rejected' end,
    review_note = trim(coalesce(p_note, '')), reviewed_by = auth.uid(), reviewed_at = now()
    where id = p_id returning * into v_request;
  return v_request;
end;
$$;
revoke execute on function aero_request_shift_correction(uuid,timestamptz,timestamptz,text) from public, anon;
revoke execute on function aero_review_shift_correction(uuid,boolean,text) from public, anon;
grant execute on function aero_request_shift_correction(uuid,timestamptz,timestamptz,text) to authenticated;
grant execute on function aero_review_shift_correction(uuid,boolean,text) to authenticated;

-- ── ESTIMATED PAY (optional, off by default) ─────────────────────────────
-- One hourly rate per person. Rates live in their own table because every
-- colleague can read aero_profiles. Staff can read their own rate only once their
-- company has switched pay on; managers read and set rates for their own
-- company only. Safe to run again.
alter table aero_companies add column if not exists show_pay boolean not null default false;

create table if not exists aero_pay_rates (
  user_id     uuid primary key references aero_profiles(id) on delete cascade,
  company_id  uuid not null references aero_companies(id) on delete cascade,
  hourly_rate numeric(8,2) not null check (hourly_rate >= 0 and hourly_rate <= 1000),
  updated_at  timestamptz not null default now()
);
create index if not exists aero_pay_rates_company_idx on aero_pay_rates(company_id);
alter table aero_pay_rates enable row level security;

drop policy if exists aero_pay_rates_read on aero_pay_rates;
create policy aero_pay_rates_read on aero_pay_rates for select to authenticated
  using (aero_pay_rates.company_id = aero_current_company_id()
         and (aero_is_manager()
              or (aero_pay_rates.user_id = auth.uid()
                  and exists (select 1 from aero_companies c
                              where c.id = aero_pay_rates.company_id and c.show_pay))));

drop policy if exists aero_pay_rates_manage on aero_pay_rates;
create policy aero_pay_rates_manage on aero_pay_rates for all to authenticated
  using (aero_pay_rates.company_id = aero_current_company_id() and aero_is_manager())
  with check (aero_pay_rates.company_id = aero_current_company_id() and aero_is_manager()
              and exists (select 1 from aero_profiles p
                          where p.id = aero_pay_rates.user_id and p.company_id = aero_pay_rates.company_id));

revoke all on table aero_pay_rates from anon;
grant select, insert, update, delete on table aero_pay_rates to authenticated;

-- Managers may change only a company's name and its pay switch.
revoke update on table aero_companies from authenticated;
grant update (name, show_pay) on table aero_companies to authenticated;

-- ── ROTA & AVAILABILITY (optional, off by default) ─────────────────────
-- A company switches this on in Company settings. Staff keep a usual week
-- and book days off; managers draft aero_shifts and publish a week when it's
-- ready. Staff only ever see the PUBLISHED copy of a shift (published_*
-- columns), so a manager can rework a week without staff watching it change.
-- Safe to run again.
alter table aero_companies add column if not exists use_rota boolean not null default false;
revoke update on table aero_companies from authenticated;
grant update (name, show_pay, use_rota) on table aero_companies to authenticated;

-- A person's usual week: one row per weekday (0 = Monday … 6 = Sunday).
create table if not exists aero_availability (
  user_id     uuid not null references aero_profiles(id) on delete cascade,
  company_id  uuid not null references aero_companies(id) on delete cascade,
  weekday     smallint not null check (weekday between 0 and 6),
  kind        text not null check (kind in ('any','between','off')),
  start_time  time,
  end_time    time,
  updated_at  timestamptz not null default now(),
  primary key (user_id, weekday),
  check (kind <> 'between' or (start_time is not null and end_time is not null and start_time <> end_time))
);
alter table aero_availability enable row level security;

drop policy if exists aero_availability_read on aero_availability;
create policy aero_availability_read on aero_availability for select to authenticated
  using (company_id = aero_current_company_id() and (user_id = auth.uid() or aero_is_manager()));

drop policy if exists aero_availability_own on aero_availability;
create policy aero_availability_own on aero_availability for all to authenticated
  using (company_id = aero_current_company_id() and user_id = auth.uid())
  with check (company_id = aero_current_company_id() and user_id = auth.uid());

-- Days a person can't work (holiday, appointments). Staff add and remove
-- their own; managers only read them while planning.
create table if not exists aero_time_off (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references aero_profiles(id) on delete cascade,
  company_id  uuid not null references aero_companies(id) on delete cascade,
  first_day   date not null,
  last_day    date not null,
  reason      text not null default '' check (length(reason) <= 200),
  created_at  timestamptz not null default now(),
  check (last_day >= first_day and last_day - first_day <= 60)
);
create index if not exists aero_time_off_company_idx on aero_time_off(company_id, first_day);
alter table aero_time_off enable row level security;

drop policy if exists aero_time_off_read on aero_time_off;
create policy aero_time_off_read on aero_time_off for select to authenticated
  using (company_id = aero_current_company_id() and (user_id = auth.uid() or aero_is_manager()));

drop policy if exists aero_time_off_add on aero_time_off;
create policy aero_time_off_add on aero_time_off for insert to authenticated
  with check (company_id = aero_current_company_id() and user_id = auth.uid());

drop policy if exists aero_time_off_remove on aero_time_off;
create policy aero_time_off_remove on aero_time_off for delete to authenticated
  using (company_id = aero_current_company_id() and user_id = auth.uid());

-- Planned aero_shifts. starts_at/ends_at/worksite_id/note are the manager's
-- draft; published_* is what staff see, copied across by aero_publish_rota().
-- A published shift the manager deletes is marked removed, so staff keep
-- seeing it until the week is published again.
create table if not exists aero_rota_shifts (
  id                     uuid primary key default gen_random_uuid(),
  company_id             uuid not null references aero_companies(id) on delete cascade,
  user_id                uuid not null references aero_profiles(id) on delete cascade,
  worksite_id            uuid references aero_worksites(id) on delete set null,
  starts_at              timestamptz not null,
  ends_at                timestamptz not null,
  note                   text not null default '' check (length(note) <= 300),
  published_starts_at    timestamptz,
  published_ends_at      timestamptz,
  published_worksite_id  uuid references aero_worksites(id) on delete set null,
  published_note         text,
  removed                boolean not null default false,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  check (ends_at > starts_at and ends_at <= starts_at + interval '16 hours')
);
create index if not exists aero_rota_company_idx on aero_rota_shifts(company_id, starts_at);
create index if not exists aero_rota_user_idx on aero_rota_shifts(user_id, published_starts_at);
alter table aero_rota_shifts enable row level security;

drop policy if exists rota_read on aero_rota_shifts;
create policy rota_read on aero_rota_shifts for select to authenticated
  using (company_id = aero_current_company_id()
         and (aero_is_manager() or (user_id = auth.uid() and published_starts_at is not null)));

drop policy if exists rota_manage on aero_rota_shifts;
create policy rota_manage on aero_rota_shifts for all to authenticated
  using (company_id = aero_current_company_id() and aero_is_manager())
  with check (company_id = aero_current_company_id() and aero_is_manager()
              and exists (select 1 from aero_profiles p
                          where p.id = aero_rota_shifts.user_id and p.company_id = aero_rota_shifts.company_id)
              and (aero_rota_shifts.worksite_id is null
                   or exists (select 1 from aero_worksites w
                              where w.id = aero_rota_shifts.worksite_id and w.company_id = aero_rota_shifts.company_id)));

revoke all on table aero_availability, aero_time_off, aero_rota_shifts from anon;
grant select, insert, update, delete on table aero_availability, aero_time_off, aero_rota_shifts to authenticated;

-- Publish one week (or any range up to a month) for the caller's company:
-- drops aero_shifts removed in the draft and copies every draft onto what staff
-- see. Returns how many aero_shifts changed.
create or replace function aero_publish_rota(p_from timestamptz, p_to timestamptz)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_company uuid := aero_current_company_id();
  v_removed integer;
  v_updated integer;
begin
  if not coalesce(aero_is_manager(), false) then raise exception 'Manager access required.'; end if;
  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '32 days' then
    raise exception 'Choose a week to publish.';
  end if;

  delete from aero_rota_shifts
   where company_id = v_company and removed
     and coalesce(published_starts_at, starts_at) >= p_from
     and coalesce(published_starts_at, starts_at) < p_to;
  get diagnostics v_removed = row_count;

  update aero_rota_shifts set
    published_starts_at   = starts_at,
    published_ends_at     = ends_at,
    published_worksite_id = worksite_id,
    published_note        = note,
    updated_at            = now()
   where company_id = v_company and not removed
     and starts_at >= p_from and starts_at < p_to
     and (published_starts_at is distinct from starts_at
          or published_ends_at is distinct from ends_at
          or published_worksite_id is distinct from worksite_id
          or published_note is distinct from note);
  get diagnostics v_updated = row_count;

  return v_removed + v_updated;
end;
$$;
revoke execute on function aero_publish_rota(timestamptz, timestamptz) from public, anon;
grant execute on function aero_publish_rota(timestamptz, timestamptz) to authenticated;


-- ── ANNOUNCEMENTS ───────────────────────────────────────────────────────
-- A manager writes a short message; everyone in that company sees it on Home
-- until they dismiss it. Dismissing records that the person read it, so the
-- manager can see who has not.
create table if not exists aero_announcements (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid not null references aero_companies(id) on delete cascade,
  author_id   uuid references aero_profiles(id) on delete set null,
  body        text not null check (length(btrim(body)) between 1 and 500),
  created_at  timestamptz not null default now(),
  expires_at  timestamptz,
  active      boolean not null default true
);
create index if not exists aero_announcements_company_idx on aero_announcements(company_id, created_at desc);
alter table aero_announcements enable row level security;

-- Staff see live ones only. Managers see every one, so they can reopen or
-- switch off something they posted earlier.
drop policy if exists aero_announcements_read on aero_announcements;
create policy aero_announcements_read on aero_announcements for select to authenticated
  using (company_id = aero_current_company_id()
         and aero_has_feature('notices')
         and (aero_is_manager()
              or (active and (expires_at is null or expires_at > now()))));

drop policy if exists aero_announcements_manage on aero_announcements;
create policy aero_announcements_manage on aero_announcements for all to authenticated
  using (company_id = aero_current_company_id() and aero_is_manager() and aero_has_feature('notices'))
  with check (company_id = aero_current_company_id() and aero_is_manager() and aero_has_feature('notices')
              and (author_id is null
                   or exists (select 1 from aero_profiles p
                              where p.id = aero_announcements.author_id
                                and p.company_id = aero_announcements.company_id)));

-- Who has seen what. A read is a fact: it can be written once and never
-- edited or withdrawn, so there is no update or delete grant below.
create table if not exists aero_announcement_reads (
  announcement_id uuid not null references aero_announcements(id) on delete cascade,
  user_id         uuid not null references aero_profiles(id) on delete cascade,
  company_id      uuid not null references aero_companies(id) on delete cascade,
  read_at         timestamptz not null default now(),
  primary key (announcement_id, user_id)
);
alter table aero_announcement_reads enable row level security;

drop policy if exists aero_announcement_reads_read on aero_announcement_reads;
create policy aero_announcement_reads_read on aero_announcement_reads for select to authenticated
  using (company_id = aero_current_company_id() and (user_id = auth.uid() or aero_is_manager()));

drop policy if exists aero_announcement_reads_own on aero_announcement_reads;
create policy aero_announcement_reads_own on aero_announcement_reads for insert to authenticated
  with check (company_id = aero_current_company_id() and user_id = auth.uid()
              and exists (select 1 from aero_announcements a
                          where a.id = aero_announcement_reads.announcement_id
                            and a.company_id = aero_announcement_reads.company_id));

revoke all on table aero_announcements, aero_announcement_reads from anon;
grant select, insert, update, delete on table aero_announcements to authenticated;
grant select, insert on table aero_announcement_reads to authenticated;


-- ── LEAVERS LOSE ACCESS ─────────────────────────────────────────────────
-- A removed (inactive) person belongs to no company as far as the policies
-- are concerned, so a session they still have open shows nothing. Managers
-- remove people through the manage-staff Edge Function, which also blocks
-- their sign-in. Still security definer: see WHO AM I? in schema.sql.
create or replace function aero_current_company_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select company_id from aero_profiles where id = auth.uid() and active
$$;

-- Update for September 2026: phone notifications (web push).
-- Run it once in the Supabase SQL editor, after the rota update. Safe to run again.
--
-- How it fits together:
--   * Each phone that taps "Turn on notifications" saves a aero_push_subscriptions row.
--   * aero_notification_prefs holds what each person wants (missing row = everything on).
--   * Triggers on aero_shifts, aero_shift_corrections and aero_publish_rota() queue a small
--     {type, id} message to the send-push Edge Function through pg_net, and a
--     pg_cron job sends {type: "tick"} every 5 minutes for late starts,
--     no-shows, long aero_shifts and shift reminders.
--   * The Edge Function re-reads everything itself with the service key and
--     records each notification in aero_push_log, so a message can only ever cause
--     the one notification that was due anyway. That is why the call needs no
--     secret, and why a failed call can never block a clock-in.

create extension if not exists pg_net with schema extensions;
create extension if not exists pg_cron;

-- One row: where the send-push function lives. Change the address here if
-- Supabase gives the function a different one.
create table if not exists aero_push_config (
  id            boolean primary key default true check (id),
  function_url  text not null
);
alter table aero_push_config enable row level security;          -- no policies: database only
revoke all on table aero_push_config from anon, authenticated;
-- Push configured explicitly at release.

-- A phone (or browser) that has allowed notifications.
create table if not exists aero_push_subscriptions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references aero_profiles(id) on delete cascade,
  company_id  uuid not null references aero_companies(id) on delete cascade,
  endpoint    text not null unique,
  p256dh      text not null,
  auth        text not null,
  created_at  timestamptz not null default now()
);
create index if not exists aero_push_subscriptions_user_idx on aero_push_subscriptions(user_id);
alter table aero_push_subscriptions enable row level security;
drop policy if exists aero_push_subscriptions_own on aero_push_subscriptions;
create policy aero_push_subscriptions_own on aero_push_subscriptions for select to authenticated
  using (user_id = auth.uid());

-- What each person wants. Everything defaults to on.
create table if not exists aero_notification_prefs (
  user_id               uuid primary key references aero_profiles(id) on delete cascade,
  company_id            uuid not null references aero_companies(id) on delete cascade,
  clock_in              boolean not null default true,
  clock_out             boolean not null default true,
  away                  boolean not null default true,
  corrections           boolean not null default true,
  late                  boolean not null default true,
  long_shift            boolean not null default true,
  correction_decisions  boolean not null default true,
  rota                  boolean not null default true,
  reminders             boolean not null default true,
  updated_at            timestamptz not null default now()
);
alter table aero_notification_prefs enable row level security;
drop policy if exists aero_notification_prefs_own on aero_notification_prefs;
create policy aero_notification_prefs_own on aero_notification_prefs for all to authenticated
  using (user_id = auth.uid() and company_id = aero_current_company_id())
  with check (user_id = auth.uid() and company_id = aero_current_company_id());

-- Every notification sent, so none is ever sent twice.
create table if not exists aero_push_log (
  key      text primary key,
  sent_at  timestamptz not null default now()
);
alter table aero_push_log enable row level security;             -- no policies: function only
revoke all on table aero_push_log from anon, authenticated;

revoke all on table aero_push_subscriptions, aero_notification_prefs from anon;
revoke all on table aero_push_subscriptions from authenticated;
grant select on table aero_push_subscriptions to authenticated;
grant select, insert, update, delete on table aero_notification_prefs to authenticated;

-- Save this phone for the signed-in person. If someone else used the same
-- phone before, it moves to the new person, so notifications follow whoever
-- is signed in.
create or replace function aero_save_push_subscription(p_endpoint text, p_p256dh text, p_auth text)
returns void
language plpgsql security definer set search_path = public as $$
declare v_company uuid := aero_current_company_id();
begin
  if v_company is null then raise exception 'Your account is inactive.'; end if;
  if p_endpoint is null or p_endpoint !~ '^https://' or length(p_endpoint) > 1000
     or coalesce(p_p256dh, '') = '' or coalesce(p_auth, '') = '' then
    raise exception 'This phone did not give a valid notification address.';
  end if;
  insert into aero_push_subscriptions (user_id, company_id, endpoint, p256dh, auth)
    values (auth.uid(), v_company, p_endpoint, p_p256dh, p_auth)
    on conflict (endpoint) do update
      set user_id = excluded.user_id, company_id = excluded.company_id,
          p256dh = excluded.p256dh, auth = excluded.auth, created_at = now();
end;
$$;

create or replace function aero_remove_push_subscription(p_endpoint text)
returns void
language sql security definer set search_path = public as $$
  delete from aero_push_subscriptions where endpoint = p_endpoint and user_id = auth.uid();
$$;

revoke execute on function aero_save_push_subscription(text, text, text) from public, anon;
revoke execute on function aero_remove_push_subscription(text) from public, anon;
grant execute on function aero_save_push_subscription(text, text, text) to authenticated;
grant execute on function aero_remove_push_subscription(text) to authenticated;

-- Queue a message for the send-push function. Never raises: a notification
-- must not be able to stop a clock-in or a publish.
create or replace function aero_push_event(p_body jsonb)
returns void
language plpgsql security definer set search_path = public, extensions as $$
declare v_url text;
begin
  select function_url into v_url from aero_push_config;
  if v_url is null then return; end if;
  perform net.http_post(
    url := v_url,
    body := p_body,
    headers := '{"Content-Type": "application/json"}'::jsonb,
    timeout_milliseconds := 10000
  );
exception when others then
  raise warning 'push_event skipped: %', sqlerrm;
end;
$$;
revoke execute on function aero_push_event(jsonb) from public, anon, authenticated;

create or replace function aero_shifts_push()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' or (old.clock_out_at is null and new.clock_out_at is not null) then
    perform aero_push_event(jsonb_build_object('type', 'shift', 'id', new.id));
  end if;
  return null;
end;
$$;
drop trigger if exists shifts_push on aero_shifts;
create trigger shifts_push after insert or update of clock_out_at on aero_shifts
  for each row execute function aero_shifts_push();

create or replace function aero_corrections_push()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' or old.status is distinct from new.status then
    perform aero_push_event(jsonb_build_object('type', 'correction', 'id', new.id));
  end if;
  return null;
end;
$$;
drop trigger if exists corrections_push on aero_shift_corrections;
create trigger corrections_push after insert or update of status on aero_shift_corrections
  for each row execute function aero_corrections_push();

-- publish_rota, as in the rota update, now also tells staff their rota is out.
create or replace function aero_publish_rota(p_from timestamptz, p_to timestamptz)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_company uuid := aero_current_company_id();
  v_removed integer;
  v_updated integer;
  v_gone    uuid[];
  v_changed uuid[];
begin
  if not coalesce(aero_is_manager(), false) then raise exception 'Manager access required.'; end if;
  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '32 days' then
    raise exception 'Choose a week to publish.';
  end if;

  -- Keep WHO was affected. A person whose only shift was taken off the rota has
  -- no shift left to find afterwards, and still needs telling.
  with gone as (
    delete from aero_rota_shifts
     where company_id = v_company and removed
       and coalesce(published_starts_at, starts_at) >= p_from
       and coalesce(published_starts_at, starts_at) < p_to
     returning user_id)
  select count(*)::int, coalesce(array_agg(distinct user_id), '{}'::uuid[])
    into v_removed, v_gone from gone;

  with changed as (
    update aero_rota_shifts set
      published_starts_at   = starts_at,
      published_ends_at     = ends_at,
      published_worksite_id = worksite_id,
      published_note        = note,
      updated_at            = now()
     where company_id = v_company and not removed
       and starts_at >= p_from and starts_at < p_to
       and (published_starts_at is distinct from starts_at
            or published_ends_at is distinct from ends_at
            or published_worksite_id is distinct from worksite_id
            or published_note is distinct from note)
     returning user_id)
  select count(*)::int, coalesce(array_agg(distinct user_id), '{}'::uuid[])
    into v_updated, v_changed from changed;

  if v_removed + v_updated > 0 then
    perform aero_push_event(jsonb_build_object(
      'type', 'rota', 'company_id', v_company, 'from', p_from, 'to', p_to, 'at', now(),
      'user_ids', (select coalesce(jsonb_agg(distinct u), '[]'::jsonb) from unnest(v_gone || v_changed) u)));
  end if;
  return v_removed + v_updated;
end;
$$;
revoke execute on function aero_publish_rota(timestamptz, timestamptz) from public, anon;
grant execute on function aero_publish_rota(timestamptz, timestamptz) to authenticated;

-- Everyone with a published shift in the range, and whether a phone notification
-- can reach them: a phone that has allowed notifications, and rota alerts not
-- switched off. Managers only, and only for their own company. It says nothing
-- about WHICH phone, and nothing about anyone without a shift.
create or replace function aero_rota_reach(p_from timestamptz, p_to timestamptz)
returns table (user_id uuid, full_name text, phones integer, wants boolean)
language sql
stable
security definer
set search_path = public
as $$
  select p.id,
         p.full_name,
         (select count(*)::int from aero_push_subscriptions s where s.user_id = p.id),
         coalesce((select np.rota from aero_notification_prefs np where np.user_id = p.id), true)
    from aero_profiles p
   where coalesce(aero_is_manager(), false)
     and p.company_id = aero_current_company_id()
     and exists (select 1 from aero_rota_shifts r
                  where r.user_id = p.id and r.company_id = p.company_id and not r.removed
                    and r.published_starts_at >= p_from and r.published_starts_at < p_to)
   order by p.full_name
$$;
revoke execute on function aero_rota_reach(timestamptz, timestamptz) from public, anon;
grant execute on function aero_rota_reach(timestamptz, timestamptz) to authenticated;

-- Every 5 minutes: late starts, no-shows, long aero_shifts and shift reminders.
-- Timer configured explicitly at release.
-- Timer configured explicitly at release.


-- Update for September 2026: only allow clock-in on site.
-- Run it once in the Supabase SQL editor. Safe to run again.
--
-- The owner's decision (17 Sep 2026), replacing "flag, never block" for
-- clock-in when a company has require_on_site on (the default):
--   * no location from the phone -> clock-in refused ("turn on location")
--   * outside the zone -> refused, with a GPS margin of up to 50m taken from
--     the accuracy the phone reports
--   * clocking OUT is never blocked: it is recorded and flagged as before,
--     so a forgotten clock-out can't keep a shift running all night.
-- A company that switches require_on_site off gets the old behaviour back.

alter table aero_companies add column if not exists require_on_site boolean not null default true;
revoke update on table aero_companies from authenticated;
grant update (name, show_pay, use_rota, require_on_site) on table aero_companies to authenticated;

-- Replaces the three-argument clock_in: keeping both would make every call
-- ambiguous. Pages that don't send p_accuracy still work (no margin).
drop function if exists aero_clock_in(uuid, double precision, double precision);

create or replace function aero_clock_in(
  p_worksite_id uuid,
  p_lat double precision default null,
  p_lng double precision default null,
  p_accuracy double precision default null
) returns aero_shifts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_company uuid := aero_current_company_id();
  v_strict  boolean;
  v_site    aero_worksites;
  v_metres  double precision;
  v_margin  double precision;
  v_ok      boolean;
  v_shift   aero_shifts;
begin
  if v_company is null then
    raise exception 'No profile for this user — ask your manager to add you.';
  end if;

  -- Serialise simultaneous clock-ins for one person before checking the open shift.
  perform 1 from aero_profiles where id = auth.uid() and active for update;
  if not found then raise exception 'Your account is inactive.'; end if;

  -- Already on shift? Hand back the open one rather than opening a second.
  select * into v_shift from aero_shifts
   where user_id = auth.uid() and clock_out_at is null
   order by clock_in_at desc limit 1;
  if found then
    return v_shift;
  end if;

  select * into v_site from aero_worksites
   where id = p_worksite_id and company_id = v_company;
  if not found then
    raise exception 'Unknown worksite.';
  end if;

  select require_on_site into v_strict from aero_companies where id = v_company;

  if p_lat is not null and p_lng is not null then
    v_metres := aero_metres_between(p_lat, p_lng, v_site.lat, v_site.lng);
    -- Phone GPS is often 20-50m out; give up to 50m of the reported accuracy.
    v_margin := least(greatest(coalesce(p_accuracy, 0), 0), 50);
    v_ok := v_metres <= v_site.radius_m + v_margin;
    if coalesce(v_strict, false) and not v_ok then
      raise exception 'You are %m from %. Move inside the site zone to clock in.',
        round(v_metres), v_site.name;
    end if;
  else
    if coalesce(v_strict, false) then
      raise exception 'Turn on location to clock in. Your phone needs to show you are at %.', v_site.name;
    end if;
    v_metres := null;
    v_ok := null;
  end if;

  insert into aero_shifts (company_id, user_id, worksite_id,
                      clock_in_lat, clock_in_lng, clock_in_metres, clock_in_ok)
  values (v_company, auth.uid(), p_worksite_id,
          p_lat, p_lng, round(v_metres)::int, v_ok)
  returning * into v_shift;

  return v_shift;
end;
$$;

revoke execute on function aero_clock_in(uuid, double precision, double precision, double precision) from public, anon;
grant execute on function aero_clock_in(uuid, double precision, double precision, double precision) to authenticated;



-- Update for September 2026: breaks.
-- Run it once in the Supabase SQL editor, after the on-site clock-in update.
-- Safe to run again.
--
-- Staff tap Start break and End break themselves. The minutes are added up on
-- the shift, and every hours figure in both apps takes them off — so an unpaid
-- lunch is no longer paid by mistake.
--
-- Two decisions worth knowing:
--   * A break is only ever unpaid time inside a shift. There is no "paid
--     break" setting, because nobody taps a break they are paid for.
--   * Clocking out closes an open break automatically. People forget, and a
--     shift left "on break" for fourteen hours would wreck the timesheet.
--
-- Each company can switch breaks off (aero_companies.use_breaks) — a yard where
-- nobody stops does not want the button on screen.

alter table aero_companies add column if not exists use_breaks boolean not null default true;
alter table aero_shifts    add column if not exists break_minutes integer not null default 0
  check (break_minutes >= 0);
alter table aero_shifts    add column if not exists break_started_at timestamptz;

-- ── START ───────────────────────────────────────────────────────────────
create or replace function aero_start_break()
returns aero_shifts
language plpgsql security definer set search_path = public
as $$
declare v_shift aero_shifts; v_company aero_companies;
begin
  select * into v_shift from aero_shifts
   where user_id = auth.uid() and clock_out_at is null
   order by clock_in_at desc limit 1;
  if not found then raise exception 'You are not clocked in.'; end if;

  select * into v_company from aero_companies where id = v_shift.company_id;
  if not coalesce(v_company.use_breaks, true) then
    raise exception 'Breaks are switched off for this company.';
  end if;
  if v_shift.break_started_at is not null then
    raise exception 'You are already on a break.';
  end if;

  update aero_shifts set break_started_at = now() where id = v_shift.id returning * into v_shift;
  return v_shift;
end;
$$;

-- ── END ─────────────────────────────────────────────────────────────────
-- Rounded to the nearest minute, and never negative if a clock drifts.
create or replace function aero_end_break()
returns aero_shifts
language plpgsql security definer set search_path = public
as $$
declare v_shift aero_shifts; v_mins integer;
begin
  select * into v_shift from aero_shifts
   where user_id = auth.uid() and clock_out_at is null
   order by clock_in_at desc limit 1;
  if not found then raise exception 'You are not clocked in.'; end if;
  if v_shift.break_started_at is null then raise exception 'You are not on a break.'; end if;

  v_mins := greatest(0, round(extract(epoch from (now() - v_shift.break_started_at)) / 60)::int);
  update aero_shifts set
    break_minutes    = break_minutes + v_mins,
    break_started_at = null
  where id = v_shift.id
  returning * into v_shift;
  return v_shift;
end;
$$;

-- ── CLOCKING OUT CLOSES AN OPEN BREAK ───────────────────────────────────
-- Same function as before, with those three lines added.
create or replace function aero_clock_out(
  p_lat double precision default null,
  p_lng double precision default null,
  p_note text default ''
) returns aero_shifts
language plpgsql security definer set search_path = public
as $$
declare
  v_site   aero_worksites;
  v_metres double precision;
  v_ok     boolean;
  v_shift  aero_shifts;
  v_mins   integer := 0;
begin
  select * into v_shift from aero_shifts
   where user_id = auth.uid() and clock_out_at is null
   order by clock_in_at desc limit 1;
  if not found then
    raise exception 'You are not clocked in.';
  end if;

  if v_shift.worksite_id is not null and p_lat is not null and p_lng is not null then
    select * into v_site from aero_worksites where id = v_shift.worksite_id;
    if found then
      v_metres := aero_metres_between(p_lat, p_lng, v_site.lat, v_site.lng);
      v_ok := v_metres <= v_site.radius_m;
    end if;
  end if;

  -- Somebody who forgot to end their break is not on a fourteen-hour lunch.
  if v_shift.break_started_at is not null then
    v_mins := greatest(0, round(extract(epoch from (now() - v_shift.break_started_at)) / 60)::int);
  end if;

  update aero_shifts set
    clock_out_at     = now(),
    clock_out_lat    = p_lat,
    clock_out_lng    = p_lng,
    clock_out_metres = round(v_metres)::int,
    clock_out_ok     = v_ok,
    break_minutes    = break_minutes + v_mins,
    break_started_at = null,
    note             = coalesce(nullif(p_note, ''), note)
  where id = v_shift.id
  returning * into v_shift;

  return v_shift;
end;
$$;

revoke execute on function aero_start_break(), aero_end_break() from public, anon;
grant execute on function aero_start_break(), aero_end_break() to authenticated;


-- Update for September 2026: the staff privacy notice.
-- Run it once in the Supabase SQL editor. Safe to run again.
--
-- The app shows every member of staff a plain-English notice about what is
-- kept about them, the first time they sign in and any time under Account.
-- The notice text lives in the pages (it changes with the company's settings);
-- this update stores the two things only the company can supply, and a record
-- that each person was shown it.
--
--   * aero_companies.privacy_contact  who staff ask about their data
--   * aero_companies.retention_text   how long records are kept, in the company's words
--   * aero_privacy_ack                who has read which version, and when
--
-- The record is its own table, not a column on aero_profiles, for the same reason
-- pay rates are: colleagues can read aero_profiles, and nobody needs to see when
-- somebody else read a notice. Staff see their own row; managers see the
-- company's. Nobody writes to it directly: aero_acknowledge_privacy() does.
--
-- Nothing here blocks anyone. The app treats a missing table as "no record
-- kept yet" and simply doesn't ask, so the pages can go out before this SQL.

alter table aero_companies add column if not exists privacy_contact text not null default ''
  check (length(privacy_contact) <= 200);
alter table aero_companies add column if not exists retention_text text not null default ''
  check (length(retention_text) <= 200);

create table if not exists aero_privacy_ack (
  user_id     uuid primary key references aero_profiles(id) on delete cascade,
  company_id  uuid not null references aero_companies(id) on delete cascade,
  version     integer not null default 1,
  seen_at     timestamptz not null default now()
);

alter table aero_privacy_ack enable row level security;
drop policy if exists aero_privacy_ack_read on aero_privacy_ack;
create policy aero_privacy_ack_read on aero_privacy_ack for select to authenticated
  using (company_id = aero_current_company_id() and (user_id = auth.uid() or aero_is_manager()));

revoke all on table aero_privacy_ack from anon, authenticated;
grant select on table aero_privacy_ack to authenticated;

-- Reading the notice again after an update replaces the old record.
create or replace function aero_acknowledge_privacy(p_version integer default 1)
returns void
language plpgsql security definer set search_path = public
as $$
declare v_company uuid := aero_current_company_id();
begin
  if v_company is null then raise exception 'Your account is inactive.'; end if;
  insert into aero_privacy_ack (user_id, company_id, version, seen_at)
    values (auth.uid(), v_company, greatest(coalesce(p_version, 1), 1), now())
    on conflict (user_id) do update
      set version = excluded.version, seen_at = now(), company_id = excluded.company_id;
end;
$$;

revoke execute on function aero_acknowledge_privacy(integer) from public, anon;
grant execute on function aero_acknowledge_privacy(integer) to authenticated;


-- Update for September 2026: a shift can only point at people and sites of its own company.
-- Run it once in the Supabase SQL editor. Safe to run again. Changes no data.
--
-- Found by the tenant isolation check (checks/isolation.mjs). Nothing leaked:
-- another company's rows stayed invisible and unchanged. But the manager rule on
-- `aero_shifts` only asked "is this row in my company?", so a manager could save a
-- shift in their own company that POINTED AT another company's worksite or
-- person. It needs that company's private ids, which nobody outside it ever
-- sees, so it is an integrity hole rather than a leak. aero_rota_shifts already asks
-- the extra question on every write; this gives aero_shifts the same rule.

drop policy if exists aero_shifts_manage on aero_shifts;
create policy aero_shifts_manage on aero_shifts for all to authenticated
  using (company_id = aero_current_company_id() and aero_is_manager())
  with check (company_id = aero_current_company_id() and aero_is_manager()
              and exists (select 1 from aero_profiles p
                          where p.id = aero_shifts.user_id and p.company_id = aero_shifts.company_id)
              and (aero_shifts.worksite_id is null
                   or exists (select 1 from aero_worksites w
                              where w.id = aero_shifts.worksite_id and w.company_id = aero_shifts.company_id)));


-- Update for September 2026: "Add a client" and per-company settings.
-- Run it once in the Supabase SQL editor. Safe to run again. Changes no data.
--
--   1. aero_platform_admins   the people (you) allowed to add client aero_companies.
--                        Nobody can read or write it from the app or the website;
--                        only the `platform` Edge Function (service key) looks at it.
--   2. aero_companies gets    time_zone (default Europe/London), currency (default GBP)
--                        and brand_name (default blank: the app says "Aero Attendance").
--   3. A FIX for a gap that was already there: the breaks and privacy-notice
--      updates added columns to aero_companies but never allowed a manager to save
--      them, so "Save" in Company settings failed with "permission denied for
--      table aero_companies". This lists every column a manager may change.
--
-- AFTER RUNNING IT, make yourself a platform admin (ONE TIME, replace the email
-- with the one you sign in with):
--
--   insert into aero_platform_admins (user_id)
--   select id from auth.users where email = 'YOUR-EMAIL-HERE'
--   on conflict do nothing;

-- ── 1. PLATFORM ADMINS ──────────────────────────────────────────────────
create table if not exists aero_platform_admins (
  user_id     uuid primary key references auth.users(id) on delete cascade,
  created_at  timestamptz not null default now()
);
alter table aero_platform_admins enable row level security;
-- No policy on purpose: with row-level security on and no policy, nobody but the
-- service key can see or change a row. The revoke is the second lock.
revoke all on table aero_platform_admins from anon, authenticated;

-- ── 2. PER-COMPANY SETTINGS ─────────────────────────────────────────────
alter table aero_companies add column if not exists time_zone  text not null default 'Europe/London'
  check (length(time_zone) between 1 and 64);
alter table aero_companies add column if not exists currency   text not null default 'GBP'
  check (currency ~ '^[A-Z]{3}$');
alter table aero_companies add column if not exists brand_name text not null default ''
  check (length(brand_name) <= 60);

-- A time zone the database does not know would only fail later, in a push
-- notification, so refuse it when it is saved. The message is shown as it is.
create or replace function aero_companies_check_settings()
returns trigger
language plpgsql
as $$
begin
  begin
    perform now() at time zone new.time_zone;
  exception when others then
    raise exception '"%" is not a time zone the database knows. Use a name like Europe/London.', new.time_zone;
  end;
  return new;
end;
$$;

drop trigger if exists companies_check_settings on aero_companies;
create trigger companies_check_settings
  before insert or update of time_zone on aero_companies
  for each row execute function aero_companies_check_settings();

-- ── 3. WHAT A MANAGER MAY CHANGE ON THEIR OWN COMPANY ───────────────────
-- Never id, created_at or anything else: a client cannot rewrite its own row's identity.
revoke update on table aero_companies from authenticated;
grant update (name, show_pay, use_rota, require_on_site, use_breaks,
              privacy_contact, retention_text, time_zone, currency, brand_name)
  on table aero_companies to authenticated;


-- Update for September 2026: managers can change a person's role, safely.
-- Run it once in the Supabase SQL editor. Safe to run again. Changes no data.
--
-- What it closes: a manager could already write to any profile in their own
-- company straight from the browser, so nothing stopped an admin (manager) making
-- themselves the owner, demoting the owner, or switching the owner off. This
-- puts the rules in the database, where the page cannot bypass them:
--   * nobody's role can be changed to or from "owner" from the app
--   * nobody can change their OWN role
--   * nobody can remove or restore themselves or the owner
-- The service key (the Edge Functions) is not held to this, because it has no
-- signed-in user: manage-staff's own checks apply there.

create or replace function aero_profiles_guard()
returns trigger
language plpgsql
as $$
declare v_me uuid := auth.uid();
begin
  if v_me is null then return new; end if;   -- the service key and the database owner

  if new.role is distinct from old.role then
    if old.role = 'owner' then raise exception 'The company owner''s role cannot be changed.'; end if;
    if new.role = 'owner'  then raise exception 'Nobody can be made the owner from the app.'; end if;
    if old.id = v_me       then raise exception 'You cannot change your own role.'; end if;
  end if;

  if new.active is distinct from old.active and (old.role = 'owner' or old.id = v_me) then
    raise exception 'You cannot remove or restore yourself or the company owner.';
  end if;

  return new;
end;
$$;

drop trigger if exists profiles_guard on aero_profiles;
create trigger profiles_guard
  before update of role, active on aero_profiles
  for each row execute function aero_profiles_guard();


-- Update for September 2026: pause a client.
-- Run it once in the Supabase SQL editor. Safe to run again. Changes no data.
--
-- The /platform page can now PAUSE a client (for example one that has not paid) and
-- un-pause them, without deleting anything. A paused company's people can still sign
-- in, but the database shows them nothing and lets them do nothing until it is
-- un-paused: aero_current_company_id() and aero_is_manager(), which every policy and function
-- depends on, stop recognising them. Their data is untouched.
--
-- `suspended` is deliberately NOT in the list of columns a manager may change: a
-- client cannot pause or un-pause itself. Only the platform function (service key) can.

alter table aero_companies add column if not exists suspended boolean not null default false;

-- Both stay security definer: see WHO AM I? in schema.sql.
create or replace function aero_current_company_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select p.company_id
  from aero_profiles p join aero_companies c on c.id = p.company_id
  where p.id = auth.uid() and p.active and not c.suspended
$$;

create or replace function aero_is_manager()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from aero_profiles p join aero_companies c on c.id = p.company_id
    where p.id = auth.uid() and p.role in ('owner','admin') and p.active and not c.suspended
  )
$$;

-- Lets the pages say "this account is paused" instead of "you are not attached to a company".
-- Answers only about the caller's own company, and only true or false.
create or replace function aero_my_company_paused()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select c.suspended from aero_profiles p join aero_companies c on c.id = p.company_id
                   where p.id = auth.uid() and p.active), false)
$$;

revoke execute on function aero_my_company_paused() from public, anon;
grant execute on function aero_my_company_paused() to authenticated;


-- ── AUDIT HISTORY ───────────────────────────────────────────────────────
-- Who did what, for the manager's Audit tab. Only the database writes to it:
-- write_audit_event is revoked from `authenticated`, so a browser cannot forge
-- or backdate an entry.
create table if not exists aero_audit_events (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid not null references aero_companies(id) on delete cascade,
  actor_id    uuid references aero_profiles(id) on delete set null,
  action      text not null check (length(trim(action)) between 1 and 80),
  entity      text not null check (length(trim(entity)) between 1 and 80),
  entity_id   uuid,
  summary     text not null check (length(trim(summary)) between 1 and 500),
  details     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);

create index if not exists aero_audit_events_company_date
  on aero_audit_events(company_id, created_at desc);

alter table aero_audit_events enable row level security;
drop policy if exists aero_audit_events_manager_read on aero_audit_events;
create policy aero_audit_events_manager_read on aero_audit_events
  for select to authenticated
  using (company_id = aero_current_company_id() and aero_is_manager());

revoke all on aero_audit_events from anon, authenticated;
grant select on aero_audit_events to authenticated;

create or replace function aero_write_audit_event(
  p_company_id uuid,
  p_actor_id uuid,
  p_action text,
  p_entity text,
  p_entity_id uuid,
  p_summary text,
  p_details jsonb default '{}'::jsonb
) returns void
language plpgsql security definer set search_path = public as $$
begin
  insert into aero_audit_events(company_id, actor_id, action, entity, entity_id, summary, details)
  values (p_company_id, p_actor_id, trim(p_action), trim(p_entity), p_entity_id,
          left(trim(p_summary), 500), coalesce(p_details, '{}'::jsonb));
end;
$$;

revoke all on function aero_write_audit_event(uuid,uuid,text,text,uuid,text,jsonb) from public, anon, authenticated;

create or replace function aero_audit_shift_correction_event()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    perform aero_write_audit_event(new.company_id, new.user_id, 'requested', 'shift_correction', new.id,
      'Staff member requested a shift correction.', jsonb_build_object('status', new.status));
  elsif tg_op = 'UPDATE' and (new.status is distinct from old.status or new.reviewed_by is distinct from old.reviewed_by) then
    perform aero_write_audit_event(new.company_id, new.reviewed_by, new.status, 'shift_correction', new.id,
      'Manager ' || new.status || ' a shift correction.', jsonb_build_object('review_note', new.review_note));
  end if;
  return new;
end;
$$;

drop trigger if exists aero_shift_corrections_audit on aero_shift_corrections;
create trigger aero_shift_corrections_audit
  after insert or update on aero_shift_corrections
  for each row execute function aero_audit_shift_correction_event();

create or replace function aero_audit_rota_event()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_action text;
begin
  v_action := case when tg_op = 'INSERT' then 'created'
                   when coalesce(new.removed, false) and not coalesce(old.removed, false) then 'removed'
                   when tg_op = 'UPDATE' then 'updated'
                   else 'changed' end;
  perform aero_write_audit_event(new.company_id, auth.uid(), v_action, 'rota_shift', new.id,
    'Manager ' || v_action || ' a rota shift.', jsonb_build_object('starts_at', new.starts_at, 'ends_at', new.ends_at));
  return new;
end;
$$;

drop trigger if exists aero_rota_shifts_audit on aero_rota_shifts;
create trigger aero_rota_shifts_audit
  after insert or update on aero_rota_shifts
  for each row execute function aero_audit_rota_event();


-- ── A MANAGER CLOSING A FORGOTTEN SHIFT ─────────────────────────────────
-- Somebody drives off without clocking out and the manager has to close it.
-- This MUST NOT be a plain update on aero_shifts: aero_clock_out() is what closes an
-- open break, and skipping it leaves break_started_at set and those minutes
-- never taken off the paid hours. It also records who did it, because a shift
-- somebody else ended is pay data and has to be attributable.
create or replace function aero_clock_out_for(p_shift_id uuid, p_reason text default '')
returns aero_shifts
language plpgsql security definer set search_path = public
as $$
declare
  v_shift aero_shifts;
  v_mins  integer := 0;
  v_who   text;
begin
  if not coalesce(aero_is_manager(), false) then
    raise exception 'Manager access required.';
  end if;

  select * into v_shift from aero_shifts
   where id = p_shift_id and company_id = aero_current_company_id();
  if not found then
    raise exception 'That shift is not one of yours.';
  end if;
  if v_shift.clock_out_at is not null then
    raise exception 'That shift is already closed.';
  end if;

  if v_shift.break_started_at is not null then
    v_mins := greatest(0, round(extract(epoch from (now() - v_shift.break_started_at)) / 60)::int);
  end if;

  update aero_shifts set
    clock_out_at     = now(),
    clock_out_ok     = null,        -- a manager closed it: nobody knows where they were
    break_minutes    = break_minutes + v_mins,
    break_started_at = null
  where id = v_shift.id
  returning * into v_shift;

  select full_name into v_who from aero_profiles where id = v_shift.user_id;
  perform aero_write_audit_event(v_shift.company_id, auth.uid(), 'clocked_out', 'shift', v_shift.id,
    'Manager clocked out ' || coalesce(v_who, 'a member of staff') || '.',
    jsonb_build_object('reason', nullif(trim(p_reason), ''), 'break_minutes_added', v_mins));

  return v_shift;
end;
$$;
revoke execute on function aero_clock_out_for(uuid, text) from public, anon;
grant execute on function aero_clock_out_for(uuid, text) to authenticated;


-- ── SHIFT HANDOVER ──────────────────────────────────────────────────────
-- The next person on a worksite sees the note the last person left.
--
-- aero_shifts_read lets a member of staff read their OWN aero_shifts only, which is right
-- and stays that way. This is the one narrow exception, and it is deliberately
-- mean with what it gives back: no parameter (so nobody can walk through the
-- company's aero_worksites — it uses the caller's own open or most recent shift), and
-- it returns the note, when that shift ended and the worksite name, but NOT who
-- wrote it, their hours or their location.
create or replace function aero_my_handover()
returns table (note text, ended_at timestamptz, worksite text)
language sql
stable
security definer
set search_path = public
as $$
  with mine as (
    select s.worksite_id
      from aero_shifts s
     where s.user_id = auth.uid()
       and s.company_id = aero_current_company_id()
       and s.worksite_id is not null
     order by (s.clock_out_at is null) desc, s.clock_in_at desc
     limit 1
  )
  select btrim(s.note), s.clock_out_at, w.name
    from aero_shifts s
    join mine on mine.worksite_id = s.worksite_id
    left join aero_worksites w on w.id = s.worksite_id
   where aero_has_feature('handover')
     and s.company_id = aero_current_company_id()
     and s.user_id <> auth.uid()
     and s.clock_out_at is not null
     and s.clock_out_at > now() - interval '24 hours'
     and coalesce(btrim(s.note), '') <> ''
   order by s.clock_out_at desc
   limit 1
$$;

revoke execute on function aero_my_handover() from public, anon;
grant execute on function aero_my_handover() to authenticated;


-- ── OVERTIME APPROVAL (optional, off by default) ────────────────────────
-- A company sets a weekly threshold in Company settings; any week a person
-- works more than that is listed for a manager to approve or reject, and
-- approved hours come out in their own column in the CSV export.
--
-- The week's hours are worked out from the aero_shifts every time, never stored and
-- kept in step, so a corrected shift cannot leave a stale figure behind. Only
-- the DECISION is stored, and it keeps the hours it was made against so a
-- manager can see if the week has moved since.
--
-- Weeks start on Monday in the company's own time zone, so a Sunday night shift
-- falls in the week the people working it would say it does.
alter table aero_companies add column if not exists overtime_weekly_hours numeric(5,2)
  check (overtime_weekly_hours is null or (overtime_weekly_hours > 0 and overtime_weekly_hours <= 168));

create table if not exists aero_overtime_decisions (
  company_id        uuid not null references aero_companies(id) on delete cascade,
  user_id           uuid not null references aero_profiles(id) on delete cascade,
  week_start        date not null,
  status            text not null check (status in ('approved','rejected')),
  hours_at_decision numeric(6,2) not null,
  note              text not null default '' check (length(note) <= 300),
  decided_by        uuid references aero_profiles(id) on delete set null,
  decided_at        timestamptz not null default now(),
  primary key (company_id, user_id, week_start)
);
alter table aero_overtime_decisions enable row level security;

drop policy if exists overtime_read on aero_overtime_decisions;
create policy overtime_read on aero_overtime_decisions for select to authenticated
  using (company_id = aero_current_company_id() and (user_id = auth.uid() or aero_is_manager()));

-- No insert/update/delete grant on purpose: aero_decide_overtime() is the only way
-- in, so every decision has an author and an audit entry.
revoke all on table aero_overtime_decisions from anon, authenticated;
grant select on table aero_overtime_decisions to authenticated;

-- NOT security definer: row-level security already gives a manager their whole
-- company and a member of staff only their own, which is exactly what is wanted.
-- Do not "optimise" it into a definer function.
create or replace function aero_overtime_weeks(p_from date, p_to date)
returns table (
  user_id   uuid,
  full_name text,
  week_start date,
  hours     numeric,
  threshold numeric,
  overtime  numeric,
  status    text,
  note      text,
  decided_at timestamptz
)
language sql
stable
set search_path = public
as $$
  with co as (
    select id, coalesce(time_zone, 'Europe/London') as tz, overtime_weekly_hours as ot
      from aero_companies
     where id = aero_current_company_id()
       and aero_has_feature('overtime')
  ),
  weeks as (
    select s.user_id,
           (date_trunc('week', s.clock_in_at at time zone co.tz))::date as week_start,
           sum(extract(epoch from (s.clock_out_at - s.clock_in_at)) / 3600.0
               - coalesce(s.break_minutes, 0) / 60.0) as hours
      from aero_shifts s
      cross join co
     where s.company_id = co.id
       and s.clock_out_at is not null
     group by 1, 2
  )
  select w.user_id,
         p.full_name,
         w.week_start,
         round(w.hours, 2),
         co.ot,
         round(w.hours - co.ot, 2),
         d.status,
         coalesce(d.note, ''),
         d.decided_at
    from weeks w
    cross join co
    join aero_profiles p on p.id = w.user_id
    left join aero_overtime_decisions d
      on d.company_id = co.id and d.user_id = w.user_id and d.week_start = w.week_start
   where co.ot is not null
     and w.hours > co.ot
     and w.week_start >= p_from
     and w.week_start <= p_to
   order by w.week_start desc, p.full_name
$$;

revoke execute on function aero_overtime_weeks(date, date) from public, anon;
grant execute on function aero_overtime_weeks(date, date) to authenticated;

-- Recomputes the hours at the moment of the decision rather than trusting
-- anything the browser sends.
create or replace function aero_decide_overtime(p_user_id uuid, p_week_start date, p_status text, p_note text default '')
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_company uuid := aero_current_company_id();
  v_tz      text;
  v_ot      numeric;
  v_hours   numeric;
  v_who     text;
begin
  if not coalesce(aero_is_manager(), false) then
    raise exception 'Manager access required.';
  end if;
  if not coalesce(aero_has_feature('overtime'), false) then
    raise exception 'Overtime is not part of this company''s plan.';
  end if;
  if p_status is null or p_status not in ('approved', 'rejected') then
    raise exception 'Choose approve or reject.';
  end if;

  select coalesce(time_zone, 'Europe/London'), overtime_weekly_hours
    into v_tz, v_ot
    from aero_companies where id = v_company;
  if v_ot is null then
    raise exception 'Overtime approval is switched off for this company.';
  end if;

  if not exists (select 1 from aero_profiles where id = p_user_id and company_id = v_company) then
    raise exception 'That person is not one of yours.';
  end if;

  select coalesce(sum(extract(epoch from (clock_out_at - clock_in_at)) / 3600.0
                      - coalesce(break_minutes, 0) / 60.0), 0)
    into v_hours
    from aero_shifts
   where company_id = v_company
     and user_id = p_user_id
     and clock_out_at is not null
     and (date_trunc('week', clock_in_at at time zone v_tz))::date = p_week_start;

  insert into aero_overtime_decisions (company_id, user_id, week_start, status, hours_at_decision, note, decided_by)
  values (v_company, p_user_id, p_week_start, p_status, round(v_hours, 2), left(coalesce(p_note, ''), 300), auth.uid())
  on conflict (company_id, user_id, week_start) do update
     set status            = excluded.status,
         hours_at_decision = excluded.hours_at_decision,
         note              = excluded.note,
         decided_by        = excluded.decided_by,
         decided_at        = now();

  select full_name into v_who from aero_profiles where id = p_user_id;
  perform aero_write_audit_event(v_company, auth.uid(), p_status, 'overtime', null,
    'Manager ' || p_status || ' overtime for ' || coalesce(v_who, 'a member of staff') ||
    ', week of ' || to_char(p_week_start, 'DD Mon YYYY') || '.',
    jsonb_build_object('week_start', p_week_start, 'hours', round(v_hours, 2),
                       'threshold', v_ot, 'note', nullif(trim(coalesce(p_note, '')), '')));
end;
$$;

revoke execute on function aero_decide_overtime(uuid, date, text, text) from public, anon;
grant execute on function aero_decide_overtime(uuid, date, text, text) to authenticated;

-- Re-issue the whole list. A column added without this is a column managers
-- cannot save, which is exactly how Company settings broke in 1.0.
revoke update on table aero_companies from authenticated;
grant update (name, show_pay, use_rota, require_on_site, use_breaks,
              privacy_contact, retention_text, time_zone, currency, brand_name,
              overtime_weekly_hours)
  on table aero_companies to authenticated;


-- ── STAFF PROFILES, CLEARING ALERTS, NOTICE NOTIFICATIONS ─────────────────
-- ── the add-on switch ────────────────────────────────────────────────────
alter table aero_company_features drop constraint if exists aero_company_features_feature_check;
alter table aero_company_features add constraint aero_company_features_feature_check
  check (feature in ('rota','pay','breaks','notices','handover','overtime','incidents','staff_profiles'));

-- ── 1. JOB ROLES ─────────────────────────────────────────────────────────
create table if not exists aero_job_roles (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid not null references aero_companies(id) on delete cascade,
  name        text not null check (length(btrim(name)) between 1 and 40),
  created_at  timestamptz not null default now()
);
create unique index if not exists aero_job_roles_company_name on aero_job_roles (company_id, lower(btrim(name)));
alter table aero_job_roles enable row level security;

drop policy if exists aero_job_roles_read on aero_job_roles;
create policy aero_job_roles_read on aero_job_roles for select to authenticated
  using (company_id = aero_current_company_id() and aero_has_feature('staff_profiles'));

drop policy if exists aero_job_roles_manage on aero_job_roles;
create policy aero_job_roles_manage on aero_job_roles for all to authenticated
  using (company_id = aero_current_company_id() and aero_is_manager() and aero_has_feature('staff_profiles'))
  with check (company_id = aero_current_company_id() and aero_is_manager() and aero_has_feature('staff_profiles'));

revoke all on table aero_job_roles from anon;
grant select, insert, update, delete on table aero_job_roles to authenticated;

-- Removing a role from the list leaves the person with no job role, nothing more.
alter table aero_profiles add column if not exists job_role_id uuid references aero_job_roles(id) on delete set null;

-- A manager writes aero_profiles from the browser, so nothing else stops them pointing a
-- person at ANOTHER company's role id. No data would leak, but it is a dangling
-- reference across a wall that is meant to be solid.
create or replace function aero_profiles_job_role_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.job_role_id is not null
     and not exists (select 1 from aero_job_roles j where j.id = new.job_role_id and j.company_id = new.company_id) then
    raise exception 'That job role is not one of yours.';
  end if;
  return new;
end;
$$;
drop trigger if exists profiles_job_role_guard on aero_profiles;
create trigger profiles_job_role_guard
  before insert or update of job_role_id on aero_profiles
  for each row when (new.job_role_id is not null)
  execute function aero_profiles_job_role_guard();

-- ── 2. STAFF DETAILS ─────────────────────────────────────────────────────
create table if not exists aero_staff_details (
  user_id          uuid primary key references aero_profiles(id) on delete cascade,
  company_id       uuid not null references aero_companies(id) on delete cascade,
  date_of_birth    date check (date_of_birth is null or date_of_birth > date '1900-01-01'),
  phone            text check (phone is null or length(phone) <= 30),
  emergency_name   text check (emergency_name is null or length(emergency_name) <= 100),
  emergency_phone  text check (emergency_phone is null or length(emergency_phone) <= 30),
  start_date       date check (start_date is null or start_date > date '1900-01-01'),
  updated_at       timestamptz not null default now(),
  updated_by       uuid references aero_profiles(id) on delete set null
);
create index if not exists aero_staff_details_company_idx on aero_staff_details(company_id);
alter table aero_staff_details enable row level security;

drop policy if exists aero_staff_details_read on aero_staff_details;
create policy aero_staff_details_read on aero_staff_details for select to authenticated
  using (company_id = aero_current_company_id() and aero_has_feature('staff_profiles')
         and (aero_is_manager() or user_id = auth.uid()));

-- No insert, update or delete grant: aero_save_staff_details() is the only way in.
revoke all on table aero_staff_details from anon, authenticated;
grant select on table aero_staff_details to authenticated;

create or replace function aero_save_staff_details(
  p_user_id uuid, p_dob date, p_phone text, p_emergency_name text, p_emergency_phone text, p_start date
) returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_company uuid := aero_current_company_id();
  v_who     text;
  v_phone   text := nullif(btrim(coalesce(p_phone, '')), '');
  v_en      text := nullif(btrim(coalesce(p_emergency_name, '')), '');
  v_ep      text := nullif(btrim(coalesce(p_emergency_phone, '')), '');
begin
  if not coalesce(aero_is_manager(), false) then raise exception 'Manager access required.'; end if;
  if not coalesce(aero_has_feature('staff_profiles'), false) then
    raise exception 'Staff aero_profiles are not part of this company''s plan.';
  end if;
  select full_name into v_who from aero_profiles where id = p_user_id and company_id = v_company;
  if not found then raise exception 'That person is not one of yours.'; end if;

  if p_dob is not null and (p_dob >= current_date or p_dob <= date '1900-01-01') then
    raise exception 'Check the date of birth.';
  end if;
  if p_start is not null and p_start <= date '1900-01-01' then raise exception 'Check the start date.'; end if;
  if length(coalesce(v_phone, '')) > 30 or length(coalesce(v_ep, '')) > 30 then
    raise exception 'A phone number can be up to 30 characters.';
  end if;
  if length(coalesce(v_en, '')) > 100 then raise exception 'The emergency contact name can be up to 100 characters.'; end if;

  if p_dob is null and v_phone is null and v_en is null and v_ep is null and p_start is null then
    delete from aero_staff_details where user_id = p_user_id;      -- nothing recorded: keep nothing
  else
    insert into aero_staff_details (user_id, company_id, date_of_birth, phone, emergency_name, emergency_phone, start_date, updated_by)
    values (p_user_id, v_company, p_dob, v_phone, v_en, v_ep, p_start, auth.uid())
    on conflict (user_id) do update
       set date_of_birth = excluded.date_of_birth, phone = excluded.phone,
           emergency_name = excluded.emergency_name, emergency_phone = excluded.emergency_phone,
           start_date = excluded.start_date, updated_at = now(), updated_by = excluded.updated_by;
  end if;

  -- That it happened, never what the details were.
  perform aero_write_audit_event(v_company, auth.uid(), 'updated', 'staff_profile', p_user_id,
    'Manager updated ' || coalesce(v_who, 'a member of staff') || '''s personal details.', '{}'::jsonb);
end;
$$;
revoke execute on function aero_save_staff_details(uuid, date, text, text, text, date) from public, anon;
grant execute on function aero_save_staff_details(uuid, date, text, text, text, date) to authenticated;

-- ── 3. CLEARING ALERTS ───────────────────────────────────────────────────
-- An alert is worked out from live data every time, so it goes away by itself once
-- the thing it is about is fixed. Clearing is for "I know, and it is fine", and it
-- is shared: what one manager clears, the others stop seeing.
create table if not exists aero_dismissed_alerts (
  company_id    uuid not null references aero_companies(id) on delete cascade,
  alert_key     text not null check (length(alert_key) between 1 and 120),
  dismissed_by  uuid references aero_profiles(id) on delete set null,
  dismissed_at  timestamptz not null default now(),
  primary key (company_id, alert_key)
);
alter table aero_dismissed_alerts enable row level security;

drop policy if exists aero_dismissed_alerts_read on aero_dismissed_alerts;
create policy aero_dismissed_alerts_read on aero_dismissed_alerts for select to authenticated
  using (company_id = aero_current_company_id() and aero_is_manager());

revoke all on table aero_dismissed_alerts from anon, authenticated;
grant select on table aero_dismissed_alerts to authenticated;

create or replace function aero_dismiss_alert(p_key text, p_summary text default '')
returns void
language plpgsql
security definer
set search_path = public
as $$
declare v_company uuid := aero_current_company_id(); v_key text := btrim(coalesce(p_key, '')); v_n integer;
begin
  if not coalesce(aero_is_manager(), false) then raise exception 'Manager access required.'; end if;
  if length(v_key) not between 1 and 120 then raise exception 'Nothing to clear.'; end if;
  -- An alert is about a shift or a rota slot, and a week on it is long over.
  delete from aero_dismissed_alerts where company_id = v_company and dismissed_at < now() - interval '7 days';
  insert into aero_dismissed_alerts (company_id, alert_key, dismissed_by)
    values (v_company, v_key, auth.uid()) on conflict do nothing;
  get diagnostics v_n = row_count;
  -- Tapping Clear twice must not log it twice.
  if v_n = 0 then return; end if;
  perform aero_write_audit_event(v_company, auth.uid(), 'cleared', 'alert', null,
    left('Manager cleared an alert: ' || coalesce(nullif(btrim(coalesce(p_summary, '')), ''), v_key), 500),
    jsonb_build_object('key', v_key));
end;
$$;
revoke execute on function aero_dismiss_alert(text, text) from public, anon;
grant execute on function aero_dismiss_alert(text, text) to authenticated;

-- ── 4. NOTICE NOTIFICATIONS ──────────────────────────────────────────────
alter table aero_notification_prefs add column if not exists notices boolean not null default true;

create or replace function aero_announcements_push()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform aero_push_event(jsonb_build_object('type', 'notice', 'id', new.id));
  return null;
end;
$$;
drop trigger if exists announcements_push on aero_announcements;
create trigger announcements_push
  after insert on aero_announcements
  for each row when (new.active)
  execute function aero_announcements_push();


-- ── CHECK THAT NOTIFICATIONS WORK ─────────────────────────────────────────
create or replace function aero_push_check()
returns bigint
language plpgsql
security definer
set search_path = public, extensions
as $$
declare v_url text; v_id bigint;
begin
  if not coalesce(aero_is_manager(), false) then raise exception 'Manager access required.'; end if;
  select function_url into v_url from aero_push_config;
  if v_url is null then raise exception 'aero_push_config has no function address, so nothing can be sent.'; end if;
  select net.http_post(
    url := v_url,
    body := jsonb_build_object('type', 'test', 'user_id', auth.uid()),
    headers := '{"Content-Type": "application/json"}'::jsonb,
    timeout_milliseconds := 10000
  ) into v_id;
  return v_id;
end;
$$;
revoke execute on function aero_push_check() from public, anon;
grant execute on function aero_push_check() to authenticated;

create or replace function aero_push_check_result(p_id bigint)
returns table (status_code integer, timed_out boolean, error_msg text, sent integer)
language sql
stable
security definer
set search_path = public
as $$
  select r.status_code,
         coalesce(r.timed_out, false),
         r.error_msg,
         coalesce(((regexp_match(r.content, '"sent"\s*:\s*([0-9]+)'))[1])::int, 0)
    from net._http_response r
   where r.id = p_id and coalesce(aero_is_manager(), false)
$$;
revoke execute on function aero_push_check_result(bigint) from public, anon;
grant execute on function aero_push_check_result(bigint) to authenticated;


create or replace function aero_clock_out(
  p_lat double precision default null,
  p_lng double precision default null,
  p_note text default ''
) returns aero_shifts
language plpgsql security definer set search_path = public
as $$
declare
  v_site   aero_worksites;
  v_metres double precision;
  v_ok     boolean;
  v_shift  aero_shifts;
  v_mins   integer := 0;
begin
  if p_lat is not null and not(p_lat between -90 and 90) then p_lat:=null;end if;
  if p_lng is not null and not(p_lng between -180 and 180) then p_lng:=null;end if;
  select * into v_shift from aero_shifts
   where user_id = auth.uid() and clock_out_at is null
   order by clock_in_at desc limit 1 for update;
  if not found then
    raise exception 'You are not clocked in.';
  end if;

  if v_shift.worksite_id is not null and p_lat is not null and p_lng is not null then
    select * into v_site from aero_worksites where id = v_shift.worksite_id;
    if found then
      v_metres := aero_metres_between(p_lat, p_lng, v_site.lat, v_site.lng);
      v_ok := v_metres <= v_site.radius_m;
    end if;
  end if;

  -- Somebody who forgot to end their break is not on a fourteen-hour lunch.
  if v_shift.break_started_at is not null then
    v_mins := greatest(0, round(extract(epoch from (now() - v_shift.break_started_at)) / 60)::int);
  end if;

  update aero_shifts set
    clock_out_at     = now(),
    clock_out_lat    = p_lat,
    clock_out_lng    = p_lng,
    clock_out_metres = round(v_metres)::int,
    clock_out_ok     = v_ok,
    break_minutes    = break_minutes + v_mins,
    break_started_at = null,
    note             = coalesce(nullif(p_note, ''), note)
  where id = v_shift.id
  returning * into v_shift;

  return v_shift;
end;
$$;
create or replace function aero_end_break()
returns aero_shifts
language plpgsql security definer set search_path = public
as $$
declare v_shift aero_shifts; v_mins integer;
begin
  select * into v_shift from aero_shifts
   where user_id = auth.uid() and clock_out_at is null
   order by clock_in_at desc limit 1 for update;
  if not found then raise exception 'You are not clocked in.'; end if;
  if v_shift.break_started_at is null then raise exception 'You are not on a break.'; end if;

  v_mins := greatest(0, round(extract(epoch from (now() - v_shift.break_started_at)) / 60)::int);
  update aero_shifts set
    break_minutes    = break_minutes + v_mins,
    break_started_at = null
  where id = v_shift.id
  returning * into v_shift;
  return v_shift;
end;
$$;
-- Canonical companies remain in Parking Ops. aero_companies holds only the
-- Attendance settings for that SAME id, never a new client identity.

do $$ begin
 if not exists(select 1 from pg_constraint where conname='aero_company_parking_fk') then
 alter table public.aero_companies add constraint aero_company_parking_fk foreign key(id) references public.companies(id) on delete cascade;
 end if;
end $$;

create or replace function public.aero_current_company_id() returns uuid
language plpgsql stable security definer set search_path='' as $$
declare result uuid;
begin
 select p.company_id into result from public.aero_profiles p
 join public.aero_companies c on c.id=p.company_id
 join private.attendance_identity() l on l.company_id=p.company_id and l.attendance_user_id=p.id
 where l.id is not null and p.id=auth.uid() and p.active and not c.suspended;
 return result;
end $$;
revoke all on function public.aero_current_company_id() from public,anon;
grant execute on function public.aero_current_company_id() to authenticated;

create or replace function public.aero_is_manager() returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.aero_profiles p where p.id=auth.uid()
 and p.company_id=public.aero_current_company_id() and p.role in ('owner','admin') and p.active)
$$;
revoke all on function public.aero_is_manager() from public,anon;
grant execute on function public.aero_is_manager() to authenticated;

-- Starts require the current gate. Finish operations remain available to the
-- owner of an open shift after entitlement/test access is revoked.
create or replace function public.aero_start_break() returns public.aero_shifts
language plpgsql security definer set search_path='' as $$
declare s public.aero_shifts;
begin
 if public.aero_current_company_id() is null then raise exception 'Attendance is not available for this account.';end if;
 select * into s from public.aero_shifts where user_id=auth.uid() and company_id=public.aero_current_company_id() and clock_out_at is null for update;
 if not found then raise exception 'You are not clocked in.';end if;
 if not (select use_breaks from public.aero_companies where id=s.company_id) then raise exception 'Breaks are switched off for this company.';end if;
 if s.break_started_at is null then update public.aero_shifts set break_started_at=now() where id=s.id returning * into s;end if;
 return s;
end $$;
revoke all on function public.aero_start_break() from public,anon;
grant execute on function public.aero_start_break() to authenticated;

-- A narrowly scoped endpoint keeps the finish UI working after pilot removal.
create or replace function public.aero_open_shift() returns jsonb
language sql stable security definer set search_path='' as $$
 select to_jsonb(s) from public.aero_shifts s where auth.uid() is not null and s.user_id=auth.uid() and s.clock_out_at is null limit 1
$$;
revoke all on function public.aero_open_shift() from public,anon;
grant execute on function public.aero_open_shift() to authenticated;

-- Essentials only. Staff can never enable a deferred feature by editing UI.
create or replace function public.aero_has_feature(p_feature text) returns boolean
language sql stable security definer set search_path='' as $$
 select public.aero_current_company_id() is not null and p_feature='breaks'
$$;
revoke all on function public.aero_has_feature(text) from public,anon;
grant execute on function public.aero_has_feature(text) to authenticated;

create or replace function public.aero_push_recipients(p_users uuid[]) returns table(user_id uuid)
language sql stable security definer set search_path='' as $$
 select p.id from public.aero_profiles p
 join public.attendance_staff_links l on l.attendance_user_id=p.id and l.company_id=p.company_id
 join public.staff s on s.id=l.staff_id and s.company_id=l.company_id
 join public.companies c on c.id=l.company_id
 join public.aero_companies a on a.id=c.id
 where p.id=any(p_users) and p.active and l.active and s.active and s.removed_at is null
 and coalesce(cardinality(s.desk_names),0)=0 and not a.suspended
 and c.suspended_at is null and c.brand->'attendance'='true'::jsonb
 and private.attendance_pilot_allowed(c.id,p.id)
$$;
revoke all on function public.aero_push_recipients(uuid[]) from public,anon,authenticated;
grant execute on function public.aero_push_recipients(uuid[]) to service_role;

-- Pilot enrolment is explicit and atomic. It never changes parking login,
-- passwords, roles, active flags or company IDs.
create or replace function public.aero_prepare_pilot(p_staff uuid,p_role text default 'staff') returns uuid
language plpgsql security definer set search_path='' as $$
declare s public.staff; c public.companies; link_id uuid;
begin
 if auth.uid() is null or not public.is_platform_admin() then raise exception 'Not allowed.';end if;
 if p_role is null or p_role not in ('staff','admin','owner') then raise exception 'Choose an Attendance role.';end if;
 select * into s from public.staff where id=p_staff for update;
 if s.id is null or not s.active or s.removed_at is not null or s.user_id is null or coalesce(cardinality(s.desk_names),0)>0 then raise exception 'Choose an active individual parking account.';end if;
 select * into c from public.companies where id=s.company_id for update;
 if c.suspended_at is not null or c.slug='platform' then raise exception 'Choose an active client company.';end if;
 if exists(select 1 from private.attendance_release where company_id=c.id and not pilot) then raise exception 'This company has already left private pilot mode.';end if;
 if exists(select 1 from public.aero_profiles where id=s.user_id and (company_id<>s.company_id or role<>p_role or not active)) then raise exception 'This account already has a different Attendance assignment.';end if;
 if exists(select 1 from public.attendance_staff_links where staff_id=s.id and attendance_user_id is not null and attendance_user_id<>s.user_id) then raise exception 'This person already has another Attendance account.';end if;
 update public.companies set brand=brand||'{"attendance":true}'::jsonb where id=c.id;
 insert into public.aero_companies(id,name,time_zone) values(c.id,c.name,c.time_zone) on conflict(id) do nothing;
 insert into public.attendance_staff_links(company_id,staff_id,attendance_user_id,active) values(c.id,s.id,s.user_id,true)
 on conflict(staff_id) do update set active=true,company_id=excluded.company_id,attendance_user_id=excluded.attendance_user_id returning id into link_id;
 insert into public.aero_profiles(id,company_id,full_name,role) values(s.user_id,c.id,s.name,p_role) on conflict(id) do nothing;
 insert into private.attendance_release(company_id,pilot) values(c.id,true) on conflict(company_id) do nothing;
 insert into private.attendance_testers(company_id,user_id,active) values(c.id,s.user_id,true) on conflict(company_id,user_id) do update set active=true;
 insert into public.activity(company_id,staff_name,action,value) select c.id,m.name||' (Parking Ops)','SETTINGS','Attendance pilot account enrolled: '||s.name from public.me() m;
 return link_id;
end $$;
revoke all on function public.aero_prepare_pilot(uuid,text) from public,anon;
grant execute on function public.aero_prepare_pilot(uuid,text) to authenticated;
revoke update(show_pay,use_rota,overtime_weekly_hours) on public.aero_companies from authenticated;

commit;
